INSERT INTO entity_citations
  (citation_id,entity_id,source_id,work_title,locus,quote,translator,translation_year,source_url,original_text_url,evidence_grade,evidence_note,needs_review,review_reason,verified_on,verify_method,display_order)
VALUES
('CIT_HYPERMNESTRA_APOLLOD','ENT_HYPERMNESTRA','SRC_APOLLODORUS_LIBRARY','Pseudo-Apollodorus, Library','Library 2.1.5','they picked out Hypermnestra as the eldest to be the wife of Lynceus, and Gorgophone to be the wife of Proteus; for Lynceus and Proteus had been borne to Egyptus by a woman of royal blood, Argyphia; but of the rest Busiris, Enceladus, Lycus, and Daiphron obtained by lot the daughters that had been borne to Danaus by Europe, to wit, Automate, Amymone, Agave, and Scaea. These daughters were borne to Danaus by a queen; but Gorgophone and Hypermnestra were borne to him by Elephantis. And Istrus got Hippodamia; Chalcodon got Rhodia; Agenor got Cleopatra; Chaetus got Asteria; Diocorystes got Hippodamia; Alces got Glauce; Alcmenor got Hippomedusa; Hippothous got Gorge; Euchenor got Iphimedusa; Hippolytus got Rhode. These ten sons were begotten on an Arabian woman; but the maidens were begotten on Hamadryad nymphs, some being daughters of Atlantia, and others of Phoebe. Agaptolemus got Pirene; Cercetes got Dorium; Eurydamas got Phartis; Aegius got Mnestra; Argius got Evippe; Archelaus got Anaxibia; Menemachus got Nelo. These seven sons were begotten on a Phoenician woman, and the maidens on an Ethiopian woman. The sons of Egyptus by Tyria got as their wives, without drawing lots, the daughters of Danaus by Memphis in virtue of the similarity of their names; thus Clitus got Clite; Sthenelus got Sthenele; Chrysippus got Chrysippe. The twelve sons of Egyptus by the Naiad nymph Caliadne cast lots for the daughters of Danaus by the Naiad nymph Polyxo: the sons were Eurylochus, Phantes, Peristhenes, Hermus, Dryas, Potamon, Cisseus, Lixus, Imbrus, Bromius, Polyctor, Chthonius; and the damsels were Autonoe, Theano, Electra, Cleopatra, Eurydice, Glaucippe, Anthelia, Cleodore, Evippe, Erato, Stygne, Bryce. The sons of Egyptus by Gorgo, cast lots for the daughters of Danaus by Pieria, and Periphas got Actaea, Oeneus got Podarce, Egyptus got Dioxippe, Menalces got Adite, Lampus got Ocypete, Idmon got Pylarge. The youngest sons of Egyptus were these: Idas got Hippodice; Daiphron got Adiante (the mother who bore these damsels was Herse); Pandion got Callidice; Arbelus got Oeme; Hyperbius got Celaeno; Hippocorystes got Hyperippe; the mother of these men was Hephaestine, and the mother of these damsels was Crino. When they had got their brides by lot, Danaus made a feast and gave his daughters daggers; and they slew their bridegrooms as they slept, all but Hypermnestra; for she saved Lynceus because he had respected her virginity 30 : wherefore Danaus shut her up and kept her under ward. But the rest of the daugters of Danaus buried the heads of their bridegrooms in Lerna 31 an','J. G. Frazer',1921,'https://www.theoi.com/Text/Apollodorus2.html',NULL,'primary-verbatim',NULL,true,'Named in the Danaid catalogue of Apollodorus 2.1.5 (Frazer); verify the section.',DATE '2026-06-26','name + substring gate against Frazer Apollodorus (theoi.com)',1),
